root.querySelector(".notes").onclick = () => { notesMode = !notesMode; render(); };
root.querySelector(".erase").onclick = () => { if (selected >= 0 && !game.puzzle[selected]) { history.push({ i: selected, v: game.values[selected], notes: game.notes[selected] }); game.values[selected] = 0; game.notes[selected] = 0; render(); save(); } };
root.querySelector(".undo").onclick = () => { const h = history.pop(); if (!h) return; game.values[h.i] = h.v; game.notes[h.i] = h.notes; selected = h.i; render(); save(); };
